/// What a compile emits: the SVG, nothing (`--check`), or the diagnostics as
/// JSON. All three run the same passes, so they agree on what a file is worth.
#[derive(Clone, Copy, PartialEq, Eq)]
enum Form {
    Svg,
    Check,
    Json,
}

/// One build of one source — the default invocation and each `--watch` turn.
/// The CLI contract lives here alone [SPEC 20]: an error is exit 1, a warning
/// prints (unless `--no-warn`) and is exit 1 under `--strict`, I/O is exit 2.
struct Build {
    form: Form,
    output: Option<PathBuf>,
    no_warn: bool,
    strict: bool,
}

impl Build {
    fn run(&self, source: &str, filename: &str, opts: &lini::Options) -> u8 {
        if self.form == Form::Json {
            let (doc, worst) = lini::diagnostics_json(source, opts, filename);
            print!("{}", doc);
            return self.exit_for(worst);
        }
        let result = match self.form {
            Form::Check => lini::check_with(source, opts).map(|diags| (None, diags)),
            _ => lini::compile_str_checked(source, opts).map(|(svg, diags)| (Some(svg), diags)),
        };
        let (svg, diags) = match result {
            Ok(built) => built,
            Err(e) => {
                eprintln!("{}", e.display_with_source(source, filename));
                return 1;
            }
        };
        if !self.no_warn {
            for d in &diags {
                eprintln!("{}", d.display_with_source(source, filename));
            }
        }
        if let Some(svg) = svg {
            match &self.output {
                Some(path) => {
                    if let Err(e) = std::fs::write(path, svg.as_bytes()) {
                        eprintln!("error: write {}: {}", path.display(), e);
                        return 2;
                    }
                }
                None => print!("{}", svg),
            }
        }
        self.exit_for(lini::Level::worst(&diags))
    }

    fn exit_for(&self, worst: Option<lini::Level>) -> u8 {
        match worst {
            Some(lini::Level::Error) => 1,
            Some(lini::Level::Warning) if self.strict => 1,
            _ => 0,
        }
    }
}

fn watch_loop(input: &Path, opts: &lini::Options, build: &Build) -> ExitCode {
    let output = build
        .output
        .as_deref()
        .expect("clap enforces -o with --watch");
    eprintln!("watching {} → {}", input.display(), output.display());
    let mut last_signature = None;
    loop {
        let signature = std::fs::metadata(input)
            .and_then(|m| m.modified())
            .ok()
            .map(|t| (t, std::fs::metadata(input).map(|m| m.len()).unwrap_or(0)));

        if signature != last_signature {
            last_signature = signature;
            recompile(input, opts, build);
        }
        std::thread::sleep(Duration::from_millis(200));
    }
}

fn run_serve(input: Option<String>, port: u16, static_mode: bool, theme: Option<&str>) -> ExitCode {
    let target = match input {
        Some(p) => {
            let path = PathBuf::from(&p);
            if !path.exists() {
                eprintln!("error: {}: no such file or directory", path.display());
                return ExitCode::from(2);
            }
            if path.is_dir() {
                lini::ServeTarget::Dir(path)
            } else {
                lini::ServeTarget::File(path)
            }
        }
        None => {
            lini::ServeTarget::Dir(std::env::current_dir().unwrap_or_else(|_| PathBuf::from(".")))
        }
    };
    // The served compiles carry the theme exactly as a `lini --theme` compile
    // does — one apply path, so the preview shows what the file will ship as.
    let theme_css = match theme {
        Some(arg) => match theme_css_for(arg, true) {
            Ok(css) => Some(css),
            Err(code) => return code,
        },
        None => None,
    };
    let opts = lini::Options {
        static_mode,
        theme_css,
        ..Default::default()
    };
    match lini::serve(target, port, opts) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::from(2)
        }
    }
}
fn run_fmt(input_arg: &str, check: bool, to_stdout: bool) -> ExitCode {
    let (filename, source) = match read_input(input_arg) {
        Ok(fs) => fs,
        Err(code) => return code,
    };

    let formatted = match lini::format_source(&source) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("{}", e.display_with_source(&source, &filename));
            return ExitCode::from(1);
        }
    };

    if check {
        if formatted == source {
            return ExitCode::SUCCESS;
        }
        eprintln!("{}: would reformat", filename);
        return ExitCode::from(1);
    }

    if input_arg == "-" || to_stdout {
        print!("{}", formatted);
    } else if formatted != source
        && let Err(e) = std::fs::write(input_arg, formatted.as_bytes())
    {
        eprintln!("error: write {}: {}", input_arg, e);
        return ExitCode::from(2);
    }
    ExitCode::SUCCESS
}

/// Read a subcommand's input file — `-` is stdin (named `<stdin>` in errors).
fn read_input(input_arg: &str) -> Result<(String, String), ExitCode> {
    if input_arg == "-" {
        let mut buf = String::new();
        if let Err(e) = std::io::stdin().read_to_string(&mut buf) {
            eprintln!("error: failed to read stdin: {}", e);
            return Err(ExitCode::from(2));
        }
        Ok(("<stdin>".to_string(), buf))
    } else {
        match std::fs::read_to_string(input_arg) {
            Ok(s) => Ok((input_arg.to_string(), s)),
            Err(e) => {
                eprintln!("error: {}: {}", input_arg, e);
                Err(ExitCode::from(2))
            }
        }
    }
}
fn run_desugar(input_arg: &str) -> ExitCode {
    let (filename, source) = match read_input(input_arg) {
        Ok(fs) => fs,
        Err(code) => return code,
    };
    match lini::desugar_source(&source) {
        Ok(s) => {
            print!("{}", s);
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("{}", e.display_with_source(&source, &filename));
            ExitCode::from(1)
        }
    }
}

/// `lini highlight` — the build-time door onto [`lini::highlight_html`], for a
/// host that renders a listing without linking the crate (the website's
/// no-dependency build; any static-site generator). `--css` prints the palette
/// those spans wear, so the markup and its colours come from one place.
///
/// It never parses, so a file mid-edit still highlights and the only failure
/// left is I/O — the same bargain an editor's tokenizer strikes [SPEC 20].
fn run_highlight(input_arg: Option<&str>, css: bool) -> ExitCode {
    if css {
        print!("{}", lini::highlight_css());
        return ExitCode::SUCCESS;
    }
    let Some(input_arg) = input_arg else {
        eprintln!("error: an input file is required — or '--css' for the palette");
        return ExitCode::from(3);
    };
    let (_, source) = match read_input(input_arg) {
        Ok(fs) => fs,
        Err(code) => return code,
    };
    print!("{}", lini::highlight_html(&source));
    ExitCode::SUCCESS
}

fn recompile(input: &Path, opts: &lini::Options, build: &Build) {
    let start = Instant::now();
    let source = match std::fs::read_to_string(input) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("error: read {}: {}", input.display(), e);
            return;
        }
    };
    if build.run(&source, &input.display().to_string(), opts) == 0 {
        let ms = start.elapsed().as_millis();
        match build.form {
            Form::Check => eprintln!("ok ({} ms) — check passed", ms),
            _ => eprintln!(
                "ok ({} ms) → {}",
                ms,
                build.output.as_deref().unwrap_or(Path::new("-")).display()
            ),
        }
    }
}

/// Resolve a `--theme` argument to its `--lini-*` CSS: a built-in name, then a
/// `light/dark` pair of built-ins, else — when `files` allows — a file path.
fn theme_css_for(arg: &str, files: bool) -> Result<String, ExitCode> {
    if let Some(css) = lini::builtin_css(arg) {
        return Ok(css);
    }
    if let Some((l, r)) = arg.split_once('/')
        && let Some(css) = lini::pair_css(l.trim(), r.trim())
    {
        return Ok(css);
    }
    if !files {
        eprintln!(
            "error: theme '{}' is not a built-in (try: {}), and --no-fs reads no theme file",
            arg,
            theme_names()
        );
        return Err(ExitCode::from(3));
    }
    match std::fs::read_to_string(arg) {
        Ok(s) => Ok(s),
        Err(e) => {
            eprintln!(
                "error: theme '{}': not a built-in (try: {}), and reading it as a file failed: {}",
                arg,
                theme_names(),
                e
            );
            Err(ExitCode::from(2))
        }
    }
}

fn theme_names() -> String {
    lini::list_themes()
        .iter()
        .map(|(n, _)| *n)
        .collect::<Vec<_>>()
        .join(", ")
}

/// `lini theme [NAME]` — list the built-in themes, or print one as `--lini-*`
/// CSS for a user to copy [SPEC 18].
fn run_theme(name: Option<&str>) -> ExitCode {
    match name {
        None => {
            for (n, desc) in lini::list_themes() {
                println!("{:15} {}", n, desc);
            }
            ExitCode::SUCCESS
        }
        Some(n) => match lini::builtin_css(n) {
            Some(css) => {
                print!("{}", css);
                ExitCode::SUCCESS
            }
            None => {
                eprintln!(
                    "error: unknown theme '{}' (try one of: {})",
                    n,
                    theme_names()
                );
                ExitCode::from(3)
            }
        },
    }
}
//! Themes: the `--theme` argument and the built-in palettes [SPEC 10/16].
//!
//! A theme is a set of `--lini-*` values. Built-ins are typed palettes here;
//! `--theme FILE` reads the same shape from CSS ([`extract_lini_vars`]). Both flow
//! through the one apply path in [`super::resolve`], so a built-in and a user file
//! are the same mechanism. `builtin_css` / `pair_css` render a palette back to CSS
//! for `lini theme` — the boilerplate a user copies.

use crate::Options;
use crate::render::values::format_value;
use crate::resolve::defaults::{hex as hx, ident as idn, light_dark as ld, rgba};
use crate::resolve::{ResolvedValue, VarTable, built_in_defaults};
use std::collections::BTreeSet;

/// Extract `(name_without_lini_prefix, raw_value_string)` pairs from CSS-like
/// text. Names without the `--lini-` prefix are skipped — those are not
/// Lini's to own.
pub fn extract_lini_vars(src: &str) -> Vec<(String, String)> {
    let mut out = Vec::new();
    let cleaned = strip_block_comments(src);
    // Split on `;` to walk declarations one at a time (works whether they sit
    // on separate lines or share a line).
    for decl in cleaned.split(';') {
        let decl = decl.trim();
        if decl.is_empty() {
            continue;
        }
        let Some(start) = decl.find("--lini-") else {
            continue;
        };
        let rest = &decl[start + "--lini-".len()..];
        let Some(colon) = rest.find(':') else {
            continue;
        };
        let name = rest[..colon].trim();
        let value = rest[colon + 1..].trim();
        // Trim any trailing `}` that landed in this segment (e.g.,
        // `gap: 10; }` after the split).
        let value = value.trim_end_matches('}').trim();
        if name.is_empty() || value.is_empty() {
            continue;
        }
        out.push((name.to_string(), value.to_string()));
    }
    out
}

/// Remove `/* … */` block comments. Themes are simple flat files; we don't
/// support nested comments.
fn strip_block_comments(src: &str) -> String {
    let mut out = String::with_capacity(src.len());
    let mut rest = src;
    while let Some(open) = rest.find("/*") {
        out.push_str(&rest[..open]);
        rest = match rest[open + 2..].find("*/") {
            Some(close) => &rest[open + 2 + close + 2..],
            None => "",
        };
    }
    out.push_str(rest);
    out
}

// ─────────────────────────── Built-in themes ───────────────────────────

/// Built-in theme names + one-line descriptions, for `lini theme`.
pub fn list_themes() -> &'static [(&'static str, &'static str)] {
    &[
        (
            "default",
            "light + dark, follows the OS (the no-flag output)",
        ),
        ("light", "the light palette alone"),
        ("dark", "the dark palette alone"),
        ("high-contrast", "maximal contrast, light + dark (a11y)"),
        (
            "blueprint",
            "white linework on cyanotype blue — the diazo print, one look",
        ),
    ]
}

/// The CSS for a built-in theme — the `--lini-*` declarations a user can copy
/// [SPEC 18]. `None` for an unknown name.
pub fn builtin_css(name: &str) -> Option<String> {
    Some(to_css(&palette(name)?))
}

/// Compose two built-ins into one adaptive theme's CSS: `light`'s palette as the
/// light arm, `dark`'s as the dark arm. `None` if either name is unknown.
pub fn pair_css(light: &str, dark: &str) -> Option<String> {
    let mut l = palette(light)?;
    let mut d = palette(dark)?;
    collapse(&mut l, 0);
    collapse(&mut d, 1);
    let opts = Options::default();
    let mut out = VarTable::new();
    let mut keys: BTreeSet<&String> = l.entries.keys().collect();
    keys.extend(d.entries.keys());
    for k in keys {
        let val = match (l.get(k), d.get(k)) {
            (Some(a), Some(b)) => {
                // Identical in both arms → a single value, no light-dark().
                if format_value(a, &l, &opts) == format_value(b, &d, &opts) {
                    a.clone()
                } else {
                    ld(a.clone(), b.clone())
                }
            }
            (Some(v), None) | (None, Some(v)) => v.clone(),
            (None, None) => continue,
        };
        out.set(k.clone(), val);
    }
    Some(to_css(&out))
}

/// The fully-resolved palette for a built-in name (`None` if unknown). Single
/// themes collapse the base light-dark() pairs to one arm, then layer their look.
fn palette(name: &str) -> Option<VarTable> {
    let mut v = built_in_defaults();
    match name {
        "default" | "auto" => {}
        "light" => collapse(&mut v, 0),
        "dark" => collapse(&mut v, 1),
        "high-contrast" => apply(&mut v, &high_contrast()),
        // One look in every mode: collapse to the dark arm — the paper is dark,
        // so every hue takes its dark-mode job — then paint the paper over it.
        "blueprint" => {
            collapse(&mut v, 1);
            apply(&mut v, &blueprint());
        }
        _ => return None,
    }
    Some(v)
}

fn apply(v: &mut VarTable, overrides: &[(&str, ResolvedValue)]) {
    for (n, val) in overrides {
        v.set(*n, val.clone());
    }
}

/// Replace every `light-dark(l, d)` with its `arm` (0 = light, 1 = dark).
fn collapse(v: &mut VarTable, arm: usize) {
    for val in v.entries.values_mut() {
        if let ResolvedValue::Call(c) = val
            && c.name == "light-dark"
            && c.args.len() == 2
        {
            *val = c.args[arm].clone();
        }
    }
}

/// Render a palette to the canonical theme CSS [SPEC 18]. `color-scheme` rides
/// the rule when adaptive; `font-family` is commented so the engine default
/// (monospace, exact text sizing) holds unless a user uncomments it.
fn to_css(vars: &VarTable) -> String {
    let opts = Options::default();
    let mut names: Vec<&String> = vars.entries.keys().collect();
    names.sort();
    let adaptive = vars.entries.values().any(ResolvedValue::is_light_dark);
    let mut out = String::new();
    out.push_str("/* lini theme — copy & edit. Colours; sizes are baked, not themeable. */\n");
    out.push_str(":root, .lini {\n");
    if adaptive {
        out.push_str("  color-scheme: light dark;\n");
    }
    for n in names {
        let v = vars.entries.get(n).unwrap();
        let css = format_value(v, vars, &opts);
        if n == "font-family" {
            // Optional: a host font; commented so monospace (exact sizing) holds.
            out.push_str(&format!("  /* --lini-font-family: {}; */\n", css));
        } else {
            out.push_str(&format!("  --lini-{}: {};\n", n, css));
        }
    }
    out.push_str("}\n");
    out
}

/// Maximal-contrast palette, light + dark (a11y). Colour only — line weights bake.
fn high_contrast() -> Vec<(&'static str, ResolvedValue)> {
    vec![
        ("bg", ld(idn("white"), idn("black"))),
        ("fg", ld(idn("black"), idn("white"))),
        ("fill", ld(idn("white"), idn("black"))),
        ("stroke", ld(idn("black"), idn("white"))),
        ("accent", ld(hx("0033cc"), hx("66aaff"))),
        ("accent-text", idn("white")),
        ("muted", ld(hx("333333"), hx("cccccc"))),
        ("group-stroke", ld(idn("black"), idn("white"))),
        (
            "group-fill",
            ld(rgba(0.0, 0.0, 0.0, 0.0), rgba(0.0, 0.0, 0.0, 0.0)),
        ),
        ("caption-color", ld(idn("black"), idn("white"))),
        ("footer-color", ld(idn("black"), idn("white"))),
    ]
}

/// The blueprint — white linework on cyanotype-blue paper, the diazo print look,
/// one look in every mode. Only the black-and-white roles are repainted; the
/// named-hue palette [SPEC 10.2] passes through as the **dark arm** it was
