const results = await Promise.allSettled([
  tools.exec_command({cmd:"rg -n --hidden 'panicked at|stack backtrace|os error [0-9]|No such file|not implemented|Unsupported|unsupported|unimplemented|TODO|FIXME|OK|success|return Ok\(String::new|return Ok\(\(\)\)' src .claude | head -140 && sed -n '1,180p' src/image.rs && sed -n '1,235p' src/diag.rs",workdir:"/workspace",max_output_tokens:8000}),
  tools.exec_command({cmd:"python3 - <<'PY'
import json,re
s=json.load(open('/logs/agent/trajectory.json'))['steps']
# Text produced by the agent, not tool outputs or user instructions.
pat=re.compile(r'evaluator|\bevaluat(?:ed|ion|ing)\b|\bscor(?:e|ed|ing)\b|reward|grading',re.I)
count=0
for z in s:
 texts=[]
 if z.get('source')=='agent':
  if z.get('message'):texts.append(('MESSAGE',str(z['message'])))
  for c in z.get('tool_calls',[]):
   for k,v in c.get('arguments',{}).items():
    if isinstance(v,str):texts.append((c['function_name']+':'+k,v))
 for origin,t in texts:
  for m in pat.finditer(t):
   ctxt=t[max(0,m.start()-130):min(len(t),m.end()+230)].replace('\n',' ')
   if 'eval.rs' in ctxt and 'evaluation' in m.group().lower():continue
   print('STEP',z['step_id'],origin,ctxt)
   count+=1
   if count>=70:break
  if count>=70:break
 if count>=70:break
print('MATCHES (cap70)',count)
PY",workdir:"/workspace",max_output_tokens:4800})
]);
for (let i=0;i<results.length;i++) text({i,result:results[i]});

