// `|image|`: a raster or SVG file, embedded.
//
// `src:` is an http(s) URL or data: URI (referenced as is) or a local path,
// read relative to the input file's directory. Rasters (sniffed by magic:
// PNG, JPEG, GIF, WebP) embed as a base64 data: URI in an `<image>`; an SVG
// file is inlined as a nested `<svg>` with its ids namespaced. `fit` maps to
// preserveAspectRatio (contain/auto: the default meet, cover: slice,
// stretch: none).

use crate::ast::{Term, Value};
use crate::compile::Ctx;
use crate::diag::Diag;
use crate::scene::{Node, SheetModel};
use crate::style::single_term;
use crate::util::{base64, f4, hash8, xml_escape};
use std::path::{Path, PathBuf};

pub enum Payload {
    Href(String),
    Svg(String),
}

pub fn is_url(s: &str) -> bool {
    let l = s.to_ascii_lowercase();
    l.starts_with("http://") || l.starts_with("https://") || l.starts_with("data:")
}

pub fn resolve_path(file: &str, src: &str) -> PathBuf {
    let base = Path::new(file).parent().unwrap_or(Path::new(""));
    base.join(src)
}

fn sniff(bytes: &[u8]) -> Option<&'static str> {
    if bytes.starts_with(b"\x89PNG\r\n\x1a\n") {
        Some("image/png")
    } else if bytes.starts_with(b"\xff\xd8\xff") {
        Some("image/jpeg")
    } else if bytes.starts_with(b"GIF87a") || bytes.starts_with(b"GIF89a") {
        Some("image/gif")
    } else if bytes.len() >= 12 && &bytes[0..4] == b"RIFF" && &bytes[8..12] == b"WEBP" {
        Some("image/webp")
    } else {
        None
    }
}

// Read and classify a local image. Err carries the reason after the dash.
pub fn load(path: &Path) -> Result<Payload, String> {
    let bytes = match std::fs::read(path) {
        Ok(b) => b,
        Err(e) => {
            if e.kind() == std::io::ErrorKind::NotFound {
                return Err("no such file".to_string());
            }
            return Err(e.to_string());
        }
    };
    if let Some(mime) = sniff(&bytes) {
        return Ok(Payload::Href(format!("data:{};base64,{}", mime, base64(&bytes))));
    }
    if let Ok(text) = std::str::from_utf8(&bytes) {
        if svg_root(text).is_some() {
            return Ok(Payload::Svg(text.to_string()));
        }
    }
    Err("not an SVG or raster (PNG/JPEG/GIF/WebP)".to_string())
}

// Resolve-time check of `src:` (and the read itself).
pub fn check_src(sheet: &SheetModel, n: &Node, file: &str, opts: &crate::Options) -> Result<(), Diag> {
    let d = match crate::icon::winning_decl(sheet, n, "src") {
        Some(d) => d,
        None => return Ok(()),
    };
    let s = match single_term(&d.value) {
        Some(Term::Str(s, _)) => s.clone(),
        Some(Term::Ident(..)) => {
            return Err(Diag::error("resolve", "'src' takes a quoted string — write src: \"…\"", d.span));
        }
        _ => return Ok(()),
    };
    if is_url(&s) {
        return Ok(());
    }
    // a read failure points at the node's own `src:`, else at the node
    let span = if n.inline.iter().any(|x| std::ptr::eq(x, d)) { d.span } else { n.span };
    if opts.no_fs {
        return Err(Diag::error(
            "asset-no-fs",
            &format!("cannot read image '{}' — local files are off (--no-fs); use an http(s) URL or a data: URI", s),
            span,
        ));
    }
    match load(&resolve_path(file, &s)) {
        Ok(_) => Ok(()),
        Err(why) => Err(Diag::error("asset-not-found", &format!("cannot read image '{}' — {}", s, why), span)),
    }
}

// Before layout: a childless image needs both sides.
pub fn check_sizes(ctx: &Ctx) -> Result<(), Diag> {
    for (i, n) in ctx.nodes.iter().enumerate() {
        if n.prim == crate::types::Prim::Image && n.children.is_empty() {
            let c = &ctx.comp[i];
            if c.width.is_none() || c.height.is_none() {
                return Err(Diag::error("missing-required-property", "'|image|' requires 'width' and 'height'", n.span));
            }
        }
    }
    Ok(())
}

// No `.lini-image` rule is ever emitted, so the image type's own user rules
// are written inline: move them from the rule-level props into `own`.
// Returns the stroke width an image's dashes assume when none is set (0).
pub fn inline_type_rules(ctx: &Ctx, n: &Node, own: &mut Vec<(String, Value)>, rule_props: &mut Vec<(String, Value)>) -> f64 {
    let rules = ctx.sheet.type_rule("image");
    if !rules.is_empty() {
        for d in &rules {
            own.retain(|e| e.0 != d.name);
            own.push((d.name.clone(), d.value.clone()));
        }
        // rule-level props as the emitted CSS sees them: every rule but the image type's
        let mut props: Vec<(String, Value)> = Vec::new();
        let mut set = |k: &str, v: &Value| {
            if let Some(e) = props.iter_mut().find(|e| e.0 == k) {
                e.1 = v.clone();
            } else {
                props.push((k.to_string(), v.clone()));
            }
        };
        for t in n.chain.iter().rev() {
            for d in crate::style::type_defaults(t) {
                set(&d.name, &d.value);
            }
            if let Some(df) = ctx.sheet.define(t) {
                for d in &df.decls {
                    set(&d.name, &d.value);
                }
            }
            if t != "image" {
                for d in ctx.sheet.type_rule(t) {
                    set(&d.name, &d.value);
                }
            }
        }
        for c in &n.classes {
            if let Some(cr) = ctx.sheet.class(c) {
                for d in &cr.decls {
                    set(&d.name, &d.value);
                }
            }
        }
        *rule_props = props;
    }
    0.0
}

fn src_of(ctx: &Ctx, i: usize) -> Option<String> {
    match ctx.nodes[i].props.get("src").and_then(single_term) {
        Some(Term::Str(s, _)) => Some(s.clone()),
        _ => None,
    }
}

// The image element (unindented; an inlined SVG's content is emitted raw,
// its closing tag as the last line).
pub fn shape_lines(ctx: &Ctx, i: usize) -> Vec<String> {
    let src = match src_of(ctx, i) {
        Some(s) => s,
        None => return vec![],
    };
    let payload = if is_url(&src) {
        Payload::Href(src.clone())
    } else {
        match load(&resolve_path(&ctx.file, &src)) {
            Ok(p) => p,
            Err(_) => return vec![],
        }
    };
// Diagnostics: errors and warnings with stable codes and source spans.

#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

impl Span {
    pub fn new(start: usize, end: usize) -> Span {
        Span { start, end }
    }
    pub fn to(self, other: Span) -> Span {
        Span { start: self.start.min(other.start), end: self.end.max(other.end) }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum Severity {
    Error,
    Warning,
}

#[derive(Debug, Clone)]
pub struct Diag {
    pub family: String,
    pub severity: Severity,
    pub message: String,
    pub span: Span,
    pub fixes: Vec<Fix>,
}

#[derive(Debug, Clone)]
pub struct Fix {
    pub message: String,
    pub span: Span,
    pub replacement: String,
}

impl Diag {
    pub fn error(family: &str, message: &str, span: Span) -> Diag {
        Diag { family: family.to_string(), severity: Severity::Error, message: message.to_string(), span, fixes: vec![] }
    }
    pub fn warning(family: &str, message: &str, span: Span) -> Diag {
        Diag { family: family.to_string(), severity: Severity::Warning, message: message.to_string(), span, fixes: vec![] }
    }
    pub fn code(&self) -> &'static str {
        family_code(&self.family)
    }
}

pub fn family_code(family: &str) -> &'static str {
    match family {
        "lex" => "L000",
        "unterminated-string" => "L001",
        "bad-escape" => "L002",
        "unexpected-char" => "L004",
        "parse" => "P000",
        "expected-token" => "P001",
        "empty-bars" => "P002",
        "invalid-id" => "P003",
        "declaration-outside-block" => "P004",
        "stylesheet-after-canvas" => "P005",
        "text-carries-children" => "P006",
        "spaced-call-paren" => "P007",
        "validate" => "V000",
        "unknown-property" => "V001",
        "class-never-worn" => "V004",
        "malformed-value" => "V005",
        "invalid-color" => "V010",
        "resolve" => "R000",
        "unknown-type" => "R001",
        "unknown-class" => "R002",
        "duplicate-id" => "R003",
        "unknown-endpoint" => "R008",
        "chain-too-short" => "R009",
        "asset-not-found" => "R010",
        "asset-no-fs" => "R024",
        "layout" => "Y000",
        "missing-required-property" => "Y001",
        "chart-data" => "Y002",
        "chart-type" => "Y009",
        "impossible-link" => "T001",
        "law-breach" => "T002",
        _ => "X000",
    }
}

// Line/column (1-based, columns counted in chars) of a byte offset.
pub fn line_col(src: &str, off: usize) -> (usize, usize) {
    let mut line = 1;
    let mut col = 1;
    for (i, c) in src.char_indices() {
        if i >= off {
            break;
        }
        if c == '\n' {
            line += 1;
            col = 1;
        } else {
            col += 1;
        }
    }
    (line, col)
}

pub fn render_text(file: &str, src: &str, d: &Diag) -> String {
    let (l, c) = line_col(src, d.span.start);
    let sev = match d.severity {
        Severity::Error => "error",
        Severity::Warning => "warning",
    };
    format!("{}:{}:{}: {}: {}", file, l, c, sev, d.message)
}

pub fn json_escape(s: &str) -> String {
    let mut o = String::new();
    for c in s.chars() {
        match c {
            '"' => o.push_str("\\\""),
            '\\' => o.push_str("\\\\"),
            '\n' => o.push_str("\\n"),
            '\r' => o.push_str("\\r"),
            '\t' => o.push_str("\\t"),
            c if (c as u32) < 0x20 => o.push_str(&format!("\\u{:04x}", c as u32)),
            c => o.push(c),
        }
    }
    o
}

pub fn render_json(file: &str, src: &str, diags: &[Diag]) -> String {
    let mut o = String::new();
    o.push_str("{\n");
    o.push_str(&format!("  \"file\": \"{}\",\n", json_escape(file)));
    if diags.is_empty() {
        o.push_str("  \"diagnostics\": []\n}\n");
        return o;
    }
    o.push_str("  \"diagnostics\": [\n");
    for (i, d) in diags.iter().enumerate() {
        let (l, c) = line_col(src, d.span.start);
        let (el, ec) = line_col(src, d.span.end);
        let sev = match d.severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
        };
        o.push_str("    {\n");
        o.push_str(&format!("      \"code\": \"{}\",\n", d.code()));
        o.push_str(&format!("      \"family\": \"{}\",\n", json_escape(&d.family)));
        o.push_str(&format!("      \"severity\": \"{}\",\n", sev));
        o.push_str(&format!("      \"message\": \"{}\",\n", json_escape(&d.message)));
        o.push_str("      \"span\": {\n");
        o.push_str(&format!("        \"start\": {},\n", d.span.start));
        o.push_str(&format!("        \"end\": {},\n", d.span.end));
        o.push_str(&format!("        \"line\": {},\n", l));
        o.push_str(&format!("        \"col\": {},\n", c));
        o.push_str(&format!("        \"endLine\": {},\n", el));
        o.push_str(&format!("        \"endCol\": {}\n", ec));
        if d.fixes.is_empty() {
            o.push_str("      }\n");
        } else {
            o.push_str("      },\n");
            o.push_str("      \"fixes\": [\n");
            for (k, f) in d.fixes.iter().enumerate() {
                o.push_str("        {\n");
                o.push_str(&format!("          \"message\": \"{}\",\n", json_escape(&f.message)));
                o.push_str(&format!("          \"start\": {},\n", f.span.start));
                o.push_str(&format!("          \"end\": {},\n", f.span.end));
                o.push_str(&format!("          \"replacement\": \"{}\"\n", json_escape(&f.replacement)));
                o.push_str(if k + 1 < d.fixes.len() { "        },\n" } else { "        }\n" });
            }
            o.push_str("      ]\n");
        }
        o.push_str(if i + 1 < diags.len() { "    },\n" } else { "    }\n" });
    }
    o.push_str("  ]\n}\n");
    o
}

